WITH enriched AS (SELECT *, AVG(rating) OVER (PARTITION BY city ORDER BY rating ASC, id ASC ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS rating_avg_2, STDDEV_SAMP(rating) OVER w_recent AS city_stddev_samp_rating, DENSE_RANK() OVER w_ordered AS rating_dense_rank FROM suppliers WINDOW w_recent AS (PARTITION BY city), w_ordered AS (PARTITION BY city ORDER BY rating DESC NULLS FIRST)) SELECT city, SORT_ARRAY(COLLECT_SET(country)) AS country_list, SUM(CASE WHEN country = 'TH' THEN rating_dense_rank ELSE 0 END) AS th_rating_dense_rank, ROUND(SUM(rating_dense_rank) / NULLIF(COUNT(CASE WHEN city = 'Berlin' THEN 1 END), 0), 2) AS rating_dense_rank_per_berlin FROM enriched GROUP BY city ORDER BY th_rating_dense_rank ASC;
